mapper.update:
UPDATE hydra_storage_lifecycle_task
SET status = #{status},
    phase = #{phase},
    error_message = #{errorMessage},
    message = #{message}
WHERE guid = #{guid}

UPDATE hydra_storage_lifecycle_task
SET status = 'BLOCKED',
    phase = #{phase},
    message = 'Lifecycle task is blocked by dependencies.',
    result_snapshot = #{resultSnapshot}
WHERE guid = #{guid}
